// Das execucoes recentes, separa as que deram erro (ate 6) para buscar
// a mensagem. Sempre sai ao menos um item, senao o fluxo para aqui.
const r = $json || {};
const l = Array.isArray(r.data) ? r.data : [];
const erros = l.filter(e => e && e.status === 'error').slice(0, 6)
  .map(e => ({ json: { execId: e.id } }));
return erros.length ? erros : [{ json: { execId: null } }];

// Junta tudo no formato que o painel Jobs & Logs desenha.
const wfResp = $('Listar fluxos').first().json || {};
const exResp = $('Listar execucoes').first().json || {};
const fluxos = (Array.isArray(wfResp.data) ? wfResp.data : []).map(w => ({
  id: String(w.id), nome: w.name || '', ativo: !!w.active, atualizado: w.updatedAt || ''
}));
const nomes = {};
fluxos.forEach(f => { nomes[f.id] = f.nome; });
const errosDet = {};
for (const item of $input.all()) {
  const d = item.json || {};
  if (!d.id) continue;
  const rd = (d.data && d.data.resultData) || {};
  const err = rd.error || {};
  errosDet[String(d.id)] = {
    msg: err.message || err.description || '',
    no: rd.lastNodeExecuted || ((err.node && err.node.name) || '')
  };
}
const execucoes = (Array.isArray(exResp.data) ? exResp.data : []).map(e => {
  const det = errosDet[String(e.id)] || null;
  return {
    id: String(e.id), fluxoId: String(e.workflowId || ''),
    fluxo: nomes[String(e.workflowId || '')] || '',
    status: e.status || (e.finished ? 'success' : 'running'),
    inicio: e.startedAt || '', fim: e.stoppedAt || '', modo: e.mode || '',
    erro: det ? det.msg : '', no: det ? det.no : ''
  };
});
return [{ json: { fluxos, execucoes } }];
